index 0000000..300bb6f
--- /dev/null
+++ b/deploy/nginx.prod.conf
@@ -0,0 +1,35 @@
+events { worker_connections 8192; }
+
+http {
+    resolver 127.0.0.11 valid=10s ipv6=off;
+    log_format replicas '$time_iso8601 $status $upstream_addr $request';
+    access_log /dev/stdout replicas;
+
+    upstream apps {
+        zone apps 64k;
+        server app:8080 resolve;
+    }
+
+    server {
+        listen 80;
+        root /usr/share/nginx/html;
+        index index.html;
+
+        location = /actuator { return 404; }
+        location ^~ /actuator/ { return 404; }
+        location /api/ {
+            proxy_pass http://apps;
+            proxy_http_version 1.1;
+            proxy_set_header Host $host;
+            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
+            proxy_connect_timeout 10s;
+            proxy_read_timeout 30s;
+            proxy_next_upstream error timeout;
+            add_header X-Replica $upstream_addr always;
+        }
+
+        location / {
+            try_files $uri $uri/ /index.html;
+        }
+    }
+}

